#!/usr/bin/env bun

import fs from 'fs'

const commitTypes = [
  'feat',
  'fix',
  'perf',
  'chore',
  'docs',
  'refactor',
  'security',
  'style',
  'test',
]

// type: subject  OR  type(scope): subject  OR  type(#123): subject  OR  type!: subject
const commitMessageRegex = new RegExp(`^(${commitTypes.join('|')})(\\([^)]+\\))?!?: .+$`)

// git autogenerated commits — skip validation
const commitFixupRegex = /^(fixup|squash|amend)!/
const mergeRegex = /^Merge /
// Strips any existing type prefix so we don't double-apply when auto-fixing
const existingPrefixRegex = /^[\w-]+(\([^)]*\))?!?:\s*/

function printExamples(): void {
  console.log('\nCommit message format:  type[(scope)]: subject')
  console.log('\nValid types:', commitTypes.join(', '))
  console.log('\nExamples (no scope):')
  console.log('  chore: update dependencies')
  console.log('  feat: add user authentication')
  console.log('  fix: handle null pointer in session cleanup')
  console.log('\nExamples (with ticket scope):')
  console.log('  fix(#2901): add VAST tag proxy endpoint for creative preview')
  console.log('  feat(#1234): add campaign budget alerts')
  console.log('\nBreaking changes — add ! after type/scope:')
  console.log('  feat!: drop support for Node 18')
  console.log('  fix(#999)!: change response shape for /campaigns\n')
}

function validateCommitMessage(commitMessage: string): boolean {
  const firstLine = commitMessage?.split('\n')[0]?.trim()
  return commitMessageRegex.test(firstLine as string)
}

async function promptForCommitType(
  consoleIterator: AsyncIterableIterator<string>
): Promise<string> {
  const promptMessage = `\nChoose a commit type:\n${commitTypes.map((type, i) => `  ${i + 1}) ${type}`).join('\n')}\nEnter number (or press ENTER for 'chore'): `

  while (true) {
    process.stdout.write(promptMessage)
    const result = await consoleIterator.next()
    const line = result.value as string
    if (!line) {
      return 'chore'
    }
    const index = parseInt(line.trim(), 10) - 1
    if (index >= 0 && index < commitTypes.length) {
      return commitTypes[index] as string
    }
    console.log('Invalid choice, please try again.')
  }
}

async function main() {
  try {
    const commitMessageFile = process.argv[2]
    if (!commitMessageFile) {
      printExamples()
      process.exit(1)
    }

    let commitMessage = fs.readFileSync(commitMessageFile, 'utf8')
    const firstLine = commitMessage.split('\n')[0]?.trim() ?? ''

    // Skip auto-generated commits
    if (commitFixupRegex.test(firstLine) || mergeRegex.test(firstLine)) {
      process.exit(0)
    }

    if (!validateCommitMessage(commitMessage)) {
      console.log(`\nInvalid or missing commit type in: "${firstLine}"`)

      const consoleIterator = console[Symbol.asyncIterator]()
      const commitType = await promptForCommitType(consoleIterator)

      // Strip any existing type prefix (including optional scope) so we don't double-apply
      const stripped = firstLine.replace(existingPrefixRegex, '')
      const subject = stripped || firstLine

      const restLines = commitMessage.split('\n').slice(1).join('\n')
      commitMessage = `${commitType}: ${subject}${restLines ? `\n${restLines}` : ''}`
    }

    fs.writeFileSync(commitMessageFile, commitMessage)

    if (!validateCommitMessage(commitMessage)) {
      console.error('\nCommit message still invalid after correction. Please follow the format:')
      printExamples()
      process.exit(1)
    }

    console.log('Commit message is valid.')
    process.exit(0)
  } catch (error) {
    console.error('An error occurred:', error)
    process.exit(1)
  }
}

main().catch((error) => {
  console.error('Error:', error)
  process.exit(1)
})
